#!name=小蚕霸王餐
#!desc=某些APP要清除缓存或者重新安装拦截广告才会生效！
#!author=奶思
#!homepage=https://github.com/fmz200/wool_scripts
#!icon=https://raw.githubusercontent.com/fmz200/wool_scripts/main/icons/gif/naisi-01.gif
#!raw-url=https://github.com/fmz200/wool_scripts/raw/main/Loon/plugin/split/partX/XiaoCanBaWangCan.lpx
#!tg-channel=https://t.me/inaisi
#!date=2026-11-11 21:17:23
#############################################


[Rewrite]
# 感谢【派大星，ZenMoFiShi，sliverkissm】分享
# 去广告（这个域名其实已经在分流中拒绝）
request if ${url} ~= /^https?:\/\/zlsdk\.1rtb\.net\/sdk\/req_ad/i then reject_dict(200)
# 红包推广 因为Loon没有url-and-header这种匹配方式，此条可能会导致软件异常
#^https:\/\/gw\.xiaocantech\.com\/rpc reject-dict
# 首页横幅推广
request if ${url} ~= /^https:\/\/web2\.realtech-inc\.com\/oss\/xc-app-assets\/configs\/common\/theme\.json/i then reject_dict(200)
# 开屏广告
request if ${url} ~= /^https:\/\/sdk\.1rtb\.net\/sdk\/req_ad\?/i then reject_dict(200)
# 更新弹窗
request if ${url} ~= /^https:\/\/gw\.xiaocantech\.com\/g\/pa/i then reject_dict(200)


[MITM]
hostname = zlsdk.1rtb.net, web2.realtech-inc.com, sdk.1rtb.net, gw.xiaocantech.com
